// Update collects changes to mutable settings for a command's Update, which
// applies them together or not at all. A setter's value is stored as text
// and parsed back like any other source's; a reset removes the stored
// value, so the flag, env var, config file or default applies again.
type Update struct{ e *engine.Edits[values] }

// SetI18nDefaultLocale sets i18n.default_locale: Locale for visitors without a chosen locale; empty means the source locale
func (u *Update) SetI18nDefaultLocale(v string) {
	u.e.Set(28, func(c *values) { c.I18nDefaultLocale = v })
}

// ResetI18nDefaultLocale removes i18n.default_locale's stored value.
func (u *Update) ResetI18nDefaultLocale() { u.e.Reset(28) }

// Key names a mutable setting, for Change.Has.
type Key string

// The mutable settings.
const (
	KeyI18nDefaultLocale Key = "i18n.default_locale"
)

// Change lists the settings whose values a write changed, for OnChange.
type Change struct{ keys []Key }

// Has reports whether any of keys changed.
func (c Change) Has(keys ...Key) bool {
	for _, k := range keys {
		for _, ck := range c.keys {
			if k == ck {
				return true
			}
		}
	}
	return false
}

// Keys returns the settings that changed, in the order the schema declares
// them.
func (c Change) Keys() []Key { return append([]Key(nil), c.keys...) }

